"""Run the full eval set against one configuration and write results."""import argparseimport jsonimport timefrom pathlib import Pathfrom src.store import VectorStorefrom src.embedder import Embedderfrom src.generate import generate, format_contextfrom eval.metrics import (rank_of_gold, recall_at_k, reciprocal_rank,                          judge_faithfulness, score_abstention)def load_questions(path="eval/questions.jsonl"):    return [json.loads(l) for l in Path(path).read_text().splitlines() if l.strip()]def main():    ap = argparse.ArgumentParser()    ap.add_argument("--name", required=True, help="variant name, e.g. baseline")    ap.add_argument("--collection", default="papers")    ap.add_argument("--embed-model", default="all-MiniLM-L6-v2")    ap.add_argument("--top-k", type=int, default=5)    ap.add_argument("--gen-model", default="llama3.1:8b")    ap.add_argument("--skip-generation", action="store_true",                    help="retrieval metrics only - fast")    ap.add_argument("--limit", type=int, default=None,                    help="only run the first N questions (for testing)")    args = ap.parse_args()    store = VectorStore(collection_name=args.collection,                        embedder=Embedder(args.embed_model))    questions = load_questions()    if args.limit:        questions = questions[:args.limit]    rows = []    t0 = time.time()    for i, q in enumerate(questions, 1):        print(f"[{i}/{len(questions)}] {q['id']}", flush=True)        hits = store.search(q["question"], k=args.top_k)        retrieved_ids = [h["id"] for h in hits]        rank = rank_of_gold(retrieved_ids, q["gold_chunk_ids"])        row = {            "id": q["id"],            "type": q["type"],            "rank": rank,            "recall@1": recall_at_k(rank, 1),            "recall@5": recall_at_k(rank, 5),            "rr": reciprocal_rank(rank),            "top_similarity": hits[0]["similarity"] if hits else None,            "retrieved": retrieved_ids,        }        if not args.skip_generation:            result = generate(q["question"], hits, model=args.gen_model)            row["answer"] = result["answer"]            row["abstained"] = result["abstained"]            row["abstention_correct"] = score_abstention(result["abstained"], q["type"])            # Judge faithfulness on ANY non-abstained answer, regardless of type.            # Unanswerable questions that produce an answer are exactly where            # hallucination matters most - see q045.            if not result["abstained"]:                j = judge_faithfulness(result["answer"], format_context(hits),                                       model=args.gen_model)                row["faithfulness"] = j["score"]                row["faithfulness_verdict"] = j["verdict"]            else:                row["faithfulness"] = None                row["faithfulness_verdict"] = None        rows.append(row)    elapsed = time.time() - t0    # ---- aggregate ----    scoreable = [r for r in rows if r["type"] != "unanswerable"]    unanswerable = [r for r in rows if r["type"] == "unanswerable"]    answerable = [r for r in rows if r["type"] == "answerable"]    summary = {        "variant": args.name,        "embed_model": args.embed_model,        "top_k": args.top_k,        "gen_model": None if args.skip_generation else args.gen_model,        "n_questions": len(rows),        "n_scoreable": len(scoreable),        "recall@1": sum(r["recall@1"] for r in scoreable) / len(scoreable),        "recall@5": sum(r["recall@5"] for r in scoreable) / len(scoreable),        "mrr": sum(r["rr"] for r in scoreable) / len(scoreable),        "elapsed_sec": round(elapsed, 1),    }    if not args.skip_generation:        abst = [r["abstention_correct"] for r in unanswerable                if r["abstention_correct"] is not None]        faith = [r["faithfulness"] for r in answerable                 if r.get("faithfulness") is not None]        faith_all = [r["faithfulness"] for r in rows                     if r.get("faithfulness") is not None]        faith_unans = [r["faithfulness"] for r in unanswerable                       if r.get("faithfulness") is not None]        summary["abstention_correct"] = sum(abst) / len(abst) if abst else None        summary["faithfulness_answerable"] = sum(faith) / len(faith) if faith else None        summary["faithfulness_all"] = sum(faith_all) / len(faith_all) if faith_all else None        summary["faithfulness_failed_abstention"] = (            sum(faith_unans) / len(faith_unans) if faith_unans else None)        summary["n_judged"] = len(faith_all)    outdir = Path("eval/results")    outdir.mkdir(parents=True, exist_ok=True)    outpath = outdir / f"{args.name}.json"    outpath.write_text(json.dumps({"summary": summary, "rows": rows}, indent=2))    print("\n" + "=" * 60)    for k, v in summary.items():        print(f"  {k:>22}: {v}")    print("=" * 60)    print(f"written to {outpath}")if __name__ == "__main__":    main()